// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IPancakePair} from "./IPancakePair.sol";
import {IUniswapV3Pool} from "./IUniswapV3Pool.sol";

/// @title IFactoryManager
/// @notice Interface for the FactoryManager contract
interface IFactoryManager {
    /// @notice Thrown when trying to set a zero address
    error ZeroAddress();

    /// @notice Thrown when the restricted function's caller is not the owner or operator address
    error OnlyOwnerOrOperator();

    /// @notice Thrown when trying to set the treasury address to the current address
    error InvalidTreasuryAddress();

    /// @notice Thrown when trying to set the operator address to the current address
    error InvalidOperatorAddress();

    /// @notice Thrown when trying to set the aggregator address to the current address
    error InvalidAggregatorAddress();

    /// @notice Thrown when setting the V2 factory address to the current address
    error InvalidV2FactoryAddress();

    /// @notice Thrown when setting the V2 router address to the current address
    error InvalidRouterAddress();

    /// @notice Thrown when setting the V2 factory fee recipient address to the current address
    error InvalidFactoryFeeToAddress();

    /// @notice Thrown when setting the V2 factory fee recipient setter address to the current owner
    error InvalidFactoryFeeToSetterAddress();

    /// @notice Thrown when attempting to withdraw liquidity when the necessary conditions aren't met
    error InvalidLiquidityWithdrawal();

    /// @notice Thrown when attempting to change feeTo or feeToSetter addresses when this contract isn't the feeToSetter
    error FactoryManagerNotFeeToSetter();

    /// @notice Thrown when the lengths of arrays used as function inputs don't match
    error LengthMismatch();

    /// @notice Thrown when attempting to set an already existing fee tier for the V3 factory
    error FeeTierExists();

    /// @notice Thrown when setting the V3 factory address to the current address
    error InvalidV3FactoryAddress();

    /// @notice Thrown when attempting to transfer factory ownership to the current owner
    error InvalidFactoryOwner();

    /// @notice Thrown when attempting to transfer factory ownership when this contract isn't the owner
    error FactoryManagerNotFactoryOwner();

    /// @notice Thrown when the batch size for fee collections exceeds the limit
    error BatchLimitExceeded();

    /// @notice Thrown when the array length for a function input is zero
    error EmptyArray();

    /// @notice Thrown when an aggregator swap transaction failed
    error InvalidSwap();

    /// @notice Sets the treasury address
    /// @dev No operator access, only owner can update the state variable
    /// @dev Reverts if the input address is zero or the current treasury address
    /// @param _treasury Address of the treasury
    function setTreasury(address _treasury) external;

    /// @notice Sets the operator address
    /// @dev No operator access, only owner can update the state variable
    /// @dev Reverts if the input address is zero or the current aggregator address
    /// @param _operator Address of the operator to set
    function setOperator(address _operator) external;

    /// @notice Sets the aggregator address used for swapping tokens through low-level calls
    /// @dev No operator access, only owner can update the state variable
    /// @dev Reverts if the input address is zero or the current aggregator address
    /// @param _aggregator Address of the aggregator contract
    function setAggregator(address _aggregator) external;

    /// @notice Sets the V2 factory contract
    /// @dev Reverts if the input address is zero or the current V2 factory address
    /// @param _factory Address of the V2 factory contract
    function setFactoryV2(address _factory) external;

    /// @notice Sets the V2 router contract
    /// @dev Reverts if the input address is zero or the current V2 factory address
    /// @param _router Address of the V2 factory contract
    function setRouterV2(address _router) external;

    /// @notice Sets the V2 factory feeTo address
    /// @dev No operator access, only owner can update the state variable
    /// @dev Reverts if the input address is already set as the feeTo
    /// @param _address Address to set as the state variable
    function setFactoryV2FeeTo(address _address) external;

    /// @notice Sets the V2 factory feeToSetter address
    /// @dev No operator access, only owner can update the state variable
    /// @dev Reverts if the input address is already set as the feeToSetter
    /// @param _address Address to set as the state variable
    function setFactoryV2FeeToSetter(address _address) external;

    /// @notice Sets the V3 factory contract
    /// @dev Reverts if the input address is zero or the current V3 factory address
    /// @param _factory Address of the V3 factory contract
    function setFactoryV3(address _factory) external;

    /// @notice Sets the V3 factory contract owner
    /// @dev No operator access, only owner can update the state variable
    /// @dev Reverts if the input address is zero or the current V3 factory owner address
    /// @param _address Address of the new V3 factory owner
    function setFactoryV3Owner(address _address) external;

    /// @notice Approves an ERC20 token to be spent by a specified address
    /// @param token Address of the token to approve for spending
    /// @param amount Amount of tokens to approve for use
    /// @param spender Address of the spender
    function approveToken(address token, address spender, uint256 amount) external;

    /// @notice Approves ERC20 tokens to be spent by a specified address in a batch
    /// @param tokens Array of token addresses to be approved for spending
    /// @param amounts Array of token amounts to approve for use
    /// @param spender Address of the spender
    function batchApproveTokens(address[] calldata tokens, address spender, uint256[] calldata amounts) external;

    /// @notice Transfers tokens to the treasury
    /// @param token Address of the token to transfer
    /// @param amount Amount of tokens to transfer
    function transferTokenToTreasury(address token, uint256 amount) external;

    /// @notice Transfers tokens to the treasury in a batch
    /// @param tokens Array of token addresses to transfer
    /// @param amounts Array of token amounts to transfer
    function batchTransferTokensToTreasury(address[] calldata tokens, uint256[] calldata amounts) external;

    /// @notice Adds a new fee tier to the factory
    /// @param fee The fee amount to enable, denominated in hundredths of a bip (i.e. 1e-6)
    /// @param tickSpacing The spacing between ticks to be enforced for all pools created with the given fee amount
    function enableFeeTier(uint24 fee, int24 tickSpacing) external;

    /// @notice Sets the protocol fee for a V3 pool
    /// @param pool Address of the pool
    /// @param feeToken0 Token0 fee
    /// @param feeToken1 Token1 fee
    function setProtocolFee(address pool, uint8 feeToken0, uint8 feeToken1) external;

    /// @notice Sets protocol fees for V3 pools
    /// @dev Watch gas limits as needed
    /// @param pools Array of pool addresses
    /// @param feesToken0 Array of token0 fees
    /// @param feesToken1 Array of token1 fees
    function setProtocolFees(address[] calldata pools, uint8[] calldata feesToken0, uint8[] calldata feesToken1)
        external;

    /// @notice Executes a single or batch swap through a decentralized exchange aggregator
    /// @param swapData Instructions for the swap transaction
